# ==================== HELPERS ====================

def hash_password(password: str) -> str:
    return hashlib.sha256(password.encode()).hexdigest()

def verify_password(password: str, password_hash: str) -> bool:
    return hash_password(password) == password_hash

def create_token(user_id: str) -> str:
    payload = {
        "user_id": user_id,
        "exp": datetime.utcnow() + timedelta(days=30)
    }
    return jwt.encode(payload, JWT_SECRET, algorithm=JWT_ALGORITHM)

async def get_current_user(credentials: HTTPAuthorizationCredentials = Depends(security)) -> User:
    try:
        token = credentials.credentials
        payload = jwt.decode(token, JWT_SECRET, algorithms=[JWT_ALGORITHM])
        user_id = payload.get("user_id")
        user_data = await db.users.find_one({"id": user_id})
        if not user_data:
            raise HTTPException(status_code=401, detail="User not found")
        return User(**user_data)
    except jwt.ExpiredSignatureError:
        raise HTTPException(status_code=401, detail="Token expired")
    except jwt.InvalidTokenError:
        raise HTTPException(status_code=401, detail="Invalid token")

async def get_admin_user(current_user: User = Depends(get_current_user)) -> User:
    if not current_user.is_admin:
        raise HTTPException(status_code=403, detail="Admin access required")
    return current_user

def get_premiumize_key_for_user(user: User) -> str:
    encrypted = (user.premiumize_api_key_encrypted or "").strip()
    if not encrypted:
        raise HTTPException(status_code=409, detail="Premiumize is not configured for this account")
    try:
        return decrypt_premiumize_key(encrypted)
    except Exception:
        logger.exception("Failed to decrypt Premiumize credential for user %s", user.id)
        raise HTTPException(status_code=500, detail="Premiumize credential is unavailable")

def get_base_url(manifest_url: str) -> str:
    """Extract base URL from manifest URL"""
    if manifest_url.endswith('/manifest.json'):
        return manifest_url[:-14]
    return manifest_url.rsplit('/', 1)[0]


# ==================== V776A UNIVERSAL ADDON INPUT ====================
def _v776a_normalize_addon_input(value: str) -> str:
    raw = str(value or "").strip()

    if not raw:
        return raw

    # Standard Stremio install links use stremio://.  The addon
    # endpoint itself is HTTPS, so canonicalize before V726 checks.
    if raw.lower().startswith("stremio://"):
        raw = "https://" + raw[len("stremio://"):]

    try:
        parsed = urlsplit(raw)
    except ValueError:
        return raw

    path = str(parsed.path or "")
    lower_path = path.lower()

    # A Stremio resource URL uniquely identifies the addon base.
    # Convert catalog/meta/stream/subtitles endpoints back to the
    # canonical manifest endpoint before installation.
    resource_markers = (
        "/catalog/",
        "/meta/",
        "/stream/",
        "/subtitles/",
    )

    for marker in resource_markers:
        index = lower_path.find(marker)
        if index >= 0:
            base_path = path[:index].rstrip("/")
            return (
                f"{parsed.scheme}://{parsed.netloc}"
                f"{base_path}/manifest.json"
            )

    if lower_path.endswith("/manifest"):
        return (
            f"{parsed.scheme}://{parsed.netloc}"
            f"{path}.json"
        )

    return raw
# ================== /V776A UNIVERSAL ADDON INPUT ====================


# ==================== V726 OUTBOUND ADDON SECURITY ====================
# Server-side addon egress is restricted to explicitly approved HTTPS
# endpoints. V726_EXTRA_ADDON_HOSTS may contain additional exact hosts.
_V726_ALLOWED_ADDON_HOSTS = frozenset({
    "07b88951aaab-jaxxx-v2.baby-beamup.club",
    "1fe84bc728af-stremio-porn.baby-beamup.club",
    "dirty-pink.ers.pw",
    "ptube.ers.pw",
    "7a82163c306e-stremio-netflix-catalog-addon.baby-beamup.club",
    "cinemeta-catalogs.strem.io",
    "mediafusion.elfhosted.com",
    "thepiratebay-plus.strem.fun",
    "torrentio.strem.fun",
    "v3-cinemeta.strem.io",
})

_V726_EXTRA_ADDON_HOSTS = frozenset(
    host.strip().rstrip(".").lower()
    for host in os.environ.get("V726_EXTRA_ADDON_HOSTS", "").split(",")
    if host.strip()
)

_V726_REDIRECT_CODES = {301, 302, 303, 307, 308}
_V726_MAX_REDIRECTS = 3


# V776B_GENERIC_PUBLIC_ADDON_HOSTS
# Permit normal public DNS addon hosts without requiring a code
# release for every new Stremio provider. _v726_validate_addon_url
# still enforces HTTPS/443, no credentials, DNS resolution to only
# globally routable addresses, and redirect revalidation.
def _v726_addon_host_allowed(host: str) -> bool:
    host = str(host or "").strip().rstrip(".").lower()

    if not host or len(host) > 253:
        return False

    # Explicitly reject local/special-use names before DNS.
    if (
        host == "localhost"
        or host == "localhost.localdomain"
        or host.endswith(".localhost")
        or host.endswith(".local")
        or host.endswith(".internal")
        or host.endswith(".home.arpa")
        or host.endswith(".test")
        or host.endswith(".invalid")
        or host.endswith(".example")
        or host.endswith(".onion")
    ):
        return False

    # Addons must use DNS hostnames, not raw IP literals.
    try:
        ipaddress.ip_address(host)
        return False
    except ValueError:
        pass

    # Reject single-label or malformed DNS names.
    labels = host.split(".")
    if len(labels) < 2:
        return False

    for label in labels:
        if not label or len(label) > 63:
            return False

        if label.startswith("-") or label.endswith("-"):
            return False

        if not all(
            ch.isalnum() or ch == "-"
            for ch in label
        ):
            return False

    return True


async def _v726_validate_addon_url(url: str) -> str:
    value = str(url or "").strip()

    if not value or len(value) > 8192:
        raise ValueError("Addon URL is empty or too long")

    if "\\" in value:
        raise ValueError("Addon URL contains a backslash")

    if any(ord(ch) < 32 or ord(ch) == 127 for ch in value):
        raise ValueError("Addon URL contains control characters")

    if any(ch.isspace() for ch in value):
        raise ValueError("Addon URL contains whitespace")

    try:
        parsed = urlsplit(value)
        host = str(parsed.hostname or "").strip().rstrip(".").lower()
        port = parsed.port
    except ValueError as exc:
        raise ValueError("Addon URL could not be parsed") from exc

    if parsed.scheme.lower() != "https":
        raise ValueError("Addon URL must use HTTPS")

    if not parsed.netloc or not host:
        raise ValueError("Addon URL has no hostname")

    if parsed.username is not None or parsed.password is not None:
        raise ValueError("Addon URL credentials are not allowed")

    if port not in (None, 443):
        raise ValueError("Addon URL must use HTTPS port 443")

    if not _v726_addon_host_allowed(host):
        raise ValueError("Addon hostname is not permitted")

    try:
        addresses = await asyncio.to_thread(
            socket.getaddrinfo,
            host,
            443,
            0,
            socket.SOCK_STREAM,
        )
    except socket.gaierror as exc:
        raise ValueError("Addon hostname could not be resolved") from exc

    resolved_ips = {
        str(entry[4][0]).split("%", 1)[0]
        for entry in addresses
        if entry and len(entry) >= 5 and entry[4]
    }

    if not resolved_ips:
        raise ValueError("Addon hostname resolved to no addresses")

    for raw_ip in resolved_ips:
        try:
            address = ipaddress.ip_address(raw_ip)
        except ValueError as exc:
            raise ValueError(
                "Addon hostname returned an invalid address"
            ) from exc

        if not address.is_global:
            raise ValueError(
                "Addon hostname resolved to a non-public address"
            )

    return value


# V776C_PINNED_ADDON_DNS
async def _v776c_resolve_public_addon_ips(host: str) -> List[str]:
    """Resolve once, validate every answer, then pin the HTTP connection."""
    hostname = str(host or "").strip().rstrip(".").lower()

    if not hostname:
        raise ValueError("Addon hostname is empty")

    try:
        addresses = await asyncio.to_thread(
            socket.getaddrinfo,
            hostname,
            443,
            0,
            socket.SOCK_STREAM,
        )
    except socket.gaierror as exc:
        raise ValueError(
            "Addon hostname could not be resolved"
        ) from exc

    resolved: List[str] = []
    seen = set()

    for entry in addresses:
        if not entry or len(entry) < 5 or not entry[4]:
            continue

        raw_ip = str(entry[4][0]).split("%", 1)[0]

        if raw_ip in seen:
            continue

        seen.add(raw_ip)

        try:
            address = ipaddress.ip_address(raw_ip)
        except ValueError as exc:
            raise ValueError(
                "Addon hostname returned an invalid address"
            ) from exc

        # Reject the entire hostname if DNS contains even one
        # private, loopback, link-local, reserved, or otherwise
        # non-global destination.
        if not address.is_global:
            raise ValueError(
                "Addon hostname resolved to a non-public address"
            )

        resolved.append(raw_ip)

    if not resolved:
        raise ValueError(
            "Addon hostname resolved to no public addresses"
        )

    return resolved


async def _v726_safe_addon_get(
    client: httpx.AsyncClient,
    url: str,
    *,
    timeout: float,
) -> httpx.Response:
    current_url = str(url or "").strip()

    for redirect_count in range(_V726_MAX_REDIRECTS + 1):
        current_url = await _v726_validate_addon_url(current_url)

        parsed = urlsplit(current_url)
        host = str(parsed.hostname or "").strip().rstrip(".").lower()

        resolved_ips = await _v776c_resolve_public_addon_ips(host)

        response = None
        last_error: Optional[Exception] = None

        for resolved_ip in resolved_ips:
            try:
                # Connect directly to the validated IP. Preserve the
                # original hostname for HTTP Host/:authority and TLS
                # SNI/certificate verification.
                pinned_url = httpx.URL(current_url).copy_with(
                    host=resolved_ip
                )

                response = await client.get(
                    pinned_url,
                    headers={"Host": host},
                    timeout=timeout,
                    follow_redirects=False,
                    extensions={"sni_hostname": host},
                )
                break
            except httpx.RequestError as exc:
                last_error = exc

        if response is None:
            if last_error is not None:
                raise last_error

            raise ValueError(
                "Addon connection could not be established"
            )

        if response.status_code not in _V726_REDIRECT_CODES:
            return response

        location = response.headers.get("location")

        if not location:
            return response

        if redirect_count >= _V726_MAX_REDIRECTS:
            raise ValueError("Addon URL exceeded redirect limit")

        # Resolve and pin the redirect destination independently.
        current_url = urljoin(current_url, location)

    raise ValueError("Addon redirect handling failed")
# ================== /V726 OUTBOUND ADDON SECURITY ====================

def get_fallback_manifest(url: str) -> Optional[Dict]:
    """Check if we have a fallback manifest for this URL"""
    for key, manifest in FALLBACK_MANIFESTS.items():
        if key in url:
            return manifest
